import assert from "node:assert/strict";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { GeneratedFile } from "../gen/generatedFile.mts";
import {
    formatFiles,
    parseGeneratorArgs,
    repoRoot,
} from "../gen/utils.mts";
import {
    type CompilerOption,
    type CompilerOptionType,
    type Declaration,
    type DeclarationGroup,
    fieldName,
    type GoValue,
    optionKind,
    type OptionsModel,
    type StoredDeclaration,
} from "./options-model.ts";
import { generateConfigSchema } from "./options-schema.ts";
import {
    options,
    pluginImportFields,
} from "./options.ts";

export { generateConfigSchema } from "./options-schema.ts";

const header = "// Code generated by tools/scripts/tsc/generate-options.ts. DO NOT EDIT.\n";
const sourceFiles = ["generate-options.ts", "options.ts", "options-model.ts", "options-schema.ts"];
const diagnosticsFile = path.join(repoRoot, "tsc/internal/diagnostics/diagnosticMessages.json");

function goValue(value: GoValue): string {
    return typeof value === "object" ? value.go : JSON.stringify(value);
}

export function compilerDeclarations(model = options): (Declaration & { group: DeclarationGroup; })[] {
    return model.compilerOptions.flatMap(option => {
        if (!option.declaration) return [];
        const { extraShortNames = [], ...metadata } = option.declaration;
        const declaration = { name: option.name, kind: optionKind(option), pathKind: option.type === "[]string" ? undefined : option.pathKind, ...metadata };
        const { description, showInSimplifiedHelpView, ...alias } = declaration;
        return [declaration, ...extraShortNames.map(shortName => ({ ...alias, shortName }))];
    });
}

function orderByName<T extends { name: string; }>(items: T[], order: string[], group: string): T[] {
    const names = new Set(items.map(item => item.name));
    const orderedNames = new Set(order);
    assert.equal(orderedNames.size, order.length, `Duplicate option in ${group} order`);
    for (const name of order) {
        assert(names.has(name), `Unknown option in ${group} order: ${name}`);
    }
    const missing = [...names].filter(name => !orderedNames.has(name));
    assert.equal(missing.length, 0, `Missing options in ${group} order: ${missing.join(", ")}`);
    return order.flatMap(name => items.filter(item => item.name === name));
}

export function validateOptions(model: OptionsModel): void {
    const constants = new Set<string>();
    const enumNames = new Set<string>();
    for (const enumDef of model.enums) {
        assert(!enumNames.has(enumDef.name), `Duplicate enum: ${enumDef.name}`);
        enumNames.add(enumDef.name);
        for (const member of enumDef.members) {
            const constant = `core.${enumDef.name}${member.name}`;
            assert(!constants.has(constant), `Duplicate enum member: ${constant}`);
            if (typeof member.value === "string") {
                assert(constants.has(`core.${enumDef.name}${member.value}`), `Unknown enum alias: ${constant}`);
            }
            else assert(Number.isInteger(member.value), `Invalid enum value: ${constant}`);
            constants.add(constant);
        }
    }
    const names = new Set<string>();
    const fields = new Set<string>();
    for (const option of model.compilerOptions) {
        for (const name of [option.name, ...(option.parseAliases ?? [])]) {
            assert(!names.has(name.toLowerCase()), `Duplicate compiler option: ${name}`);
            names.add(name.toLowerCase());
        }
        assert(!fields.has(fieldName(option)), `Duplicate compiler field: ${fieldName(option)}`);
        fields.add(fieldName(option));
        if (option.declaration?.affectsSemanticDiagnostics) {
            assert(option.declaration.affectsBuildInfo, `Semantic diagnostics must affect build info: ${option.name}`);
        }
        if (option.transpile) {
            const { value, declarationValue, unless } = option.transpile;
            assert(value === "clear" || option.type === "Tristate", `Non-boolean transpile value: ${option.name}`);
            assert(declarationValue === undefined || option.type === "Tristate", `Non-boolean declaration value: ${option.name}`);
            if (unless) assert(model.compilerOptions.some(option => option.name === unless && option.type === "Tristate"), `Unknown transpile condition: ${unless}`);
        }
        if (optionKind(option) === "Enum") assert(enumNames.has(option.type), `Unknown enum type: ${option.type}`);
        if (option.jsconfigDefault !== undefined) {
            const expected = option.type === "Tristate" ? "boolean" : option.type === "*int" ? "number" : "string";
            assert.equal(typeof option.jsconfigDefault, expected, `Invalid jsconfig default: ${option.name}`);
        }
    }
    for (const group of [model.typeAcquisition, model.buildOptions]) {
        const fields = group.flatMap(option => option.field ? [option.field.name] : []);
        assert.equal(new Set(fields).size, fields.length, "Duplicate stored option field");
        for (const option of group) {
            if (option.field) assert.equal(optionKind({ name: option.name, type: option.field.type }), option.kind, `Mismatched field type: ${option.name}`);
        }
    }
    const compiler = compilerDeclarations(model);
    for (const group of ["commonOptionsWithBuild", "optionsForCompiler"] as const) {
        orderByName(compiler.filter(declaration => declaration.group === group), model.declarationOrder[group], group);
    }
    orderByName(model.buildOptions.filter(option => option.field), model.buildOptionFieldOrder, "BuildOptions fields");
    const declarations = [...compiler, ...model.typeAcquisition, ...model.buildOptions, ...model.rootOptions, ...Object.values(model.elements)];
    for (const declaration of declarations) {
        if (declaration.kind === "Enum") {
            assert(model.enumMaps[declaration.name], `Missing enum map: ${declaration.name}`);
        }
        if (declaration.kind === "List" || declaration.kind === "ListOrElement") {
            assert(model.elements[declaration.name], `Missing list element: ${declaration.name}`);
        }
        assert(declaration.extraValidation === undefined || declaration.extraValidation === "locale", `Invalid extra validation: ${declaration.extraValidation}`);
        for (const value of Object.values(declaration)) {
            if (typeof value === "object" && value !== null && "go" in value) {
                assert(/^(?:core|diagnostics)\.[A-Za-z_]\w*$/.test(value.go), `Invalid Go reference: ${value.go}`);
            }
        }
    }
    for (const [name, map] of Object.entries(model.enumMaps)) {
        assert(map.values.length, `Empty enum map: ${name}`);
        const keys = map.values.map(entry => entry.name);
        assert.equal(new Set(keys).size, keys.length, `Duplicate enum keys: ${name}`);
        assert(keys.every(key => key === key.toLowerCase()), `Enum keys must be lowercase: ${name}`);
        for (const entry of map.values) {
            if (typeof entry.value === "object") assert(constants.has(entry.value.go), `Unknown enum constant: ${entry.value.go}`);
        }
    }
}

function sectionComment(section: string | undefined): string {
    return section ? `\n// ${section.replaceAll("\n", "\n// ")}\n\n` : "";
}

type GoCompilerOptionType =
    | CompilerOptionType
    | "tspath.RootedFilePath"
    | "tspath.RootedDirectoryPath"
    | "[]tspath.RootedDirectoryPath"
    | "tspath.RootedPath"
    | "tspath.SourceMapLocation";

function goType(option: CompilerOption): GoCompilerOptionType {
    switch (option.pathKind) {
        case "file":
            return "tspath.RootedFilePath";
        case "directory":
            return option.type === "[]string" ? "[]tspath.RootedDirectoryPath" : "tspath.RootedDirectoryPath";
        case "fileOrDirectory":
            return "tspath.RootedPath";
        case "sourceMapLocation":
            return "tspath.SourceMapLocation";
        default:
            return option.type;
    }
}

function coreOptions(): string {
    const fields = options.compilerOptions.map(option => {
        const comments = [
            ...(option.comment ? [option.comment] : []),
            ...(option.deprecated ? ["Deprecated: Do not use outside of options parsing and validation."] : []),
        ].map(comment => `// ${comment}\n`).join("");
        return `${sectionComment(option.section)}${comments}${fieldName(option)} ${goType(option)} \`json:"${option.name},omitzero"\``;
    });
    return `type PluginImport struct {
${pluginImportFields.map(field => `${fieldName(field)} ${field.type} \`json:"${field.name}"\``).join("\n")}
}

// CompilerOptions contains the compiler options exposed by the API.
type CompilerOptions struct {
    _ noCopy
    ${fields.join("\n")}
}

// Clone creates a shallow copy of the CompilerOptions.
func (options *CompilerOptions) Clone() *CompilerOptions {
    return &CompilerOptions{
        ${options.compilerOptions.map(option => `${fieldName(option)}: options.${fieldName(option)},`).join("\n")}
    }
}

// Equals reports whether all stored option values are equal, including nil versus empty collections.
// Paths are compared by ordered entries, ignoring backing-storage allocation.
${optionsEquality("CompilerOptions", options.compilerOptions.map(option => ({ name: fieldName(option), type: goType(option) })))}
`;
}

export function generateCompilerOptionsAPI(model = options): string {
    const imports = new Set<string>();
    function typeName(option: CompilerOption): string {
        switch (option.pathKind) {
            case "file":
                imports.add("RootedFilePath");
                return "RootedFilePath";
            case "directory":
                imports.add("RootedDirectoryPath");
                return option.type === "[]string" ? "RootedDirectoryPath[]" : "RootedDirectoryPath";
            case "fileOrDirectory":
                imports.add("RootedPath");
                return "RootedPath";
            case "sourceMapLocation":
                return "string";
        }
        switch (option.type) {
            case "Tristate":
                return "boolean";
            case "string":
                return "string";
            case "*int":
                return "number";
            case "[]string":
                return "string[]";
            case "[]PluginImport":
                return "PluginImport[]";
            case "*collections.OrderedMap[string, []string]":
                return "Record<string, string[]>";
            default:
                assert(model.enums.some(definition => definition.name === option.type && definition.api), `Missing API enum: ${option.type}`);
                imports.add(option.type);
                return option.type;
        }
    }
    const fields = model.compilerOptions.filter(option => !option.internal && !option.deprecated).map(option => {
        const comment = option.comment ? `/** ${option.comment.replaceAll("*/", "*\\/").replaceAll("\n", "\n * ")} */\n` : "";
        return `${sectionComment(option.section)}${comment}${option.name}?: ${typeName(option)} | undefined;`;
    });
    const pluginFields = pluginImportFields.map(field => `${field.name}: ${typeName(field)};`);
    const enumNames = [...imports].sort();
    const pathTypes = enumNames.filter(name => name.startsWith("Rooted"));
    const optionEnums = enumNames.filter(name => !name.startsWith("Rooted"));
    const enumPath = (name: string) => `../../enums/${name[0].toLowerCase() + name.slice(1)}.js`;
    return `${header}
${optionEnums.map(name => `import type { ${name} } from "${enumPath(name)}";`).join("\n")}
${pathTypes.length ? `import type {\n    ${pathTypes.join(",\n    ")},\n} from "../ast/index.ts";` : ""}

${optionEnums.map(name => `export { ${name} } from "${enumPath(name)}";`).join("\n")}

/** CompilerOptions contains the compiler options exposed by the API. */
export interface CompilerOptions {
${fields.join("\n")}
}

export interface PluginImport {
${pluginFields.join("\n")}
}
`;
}

export function generatePrepareCompilerOptionsAPI(model = options): string {
    const pathOptions = model.compilerOptions.filter(option => (option.pathKind === "file" || option.pathKind === "directory" || option.pathKind === "fileOrDirectory"));
    const converter = (option: CompilerOption): string => {
        const value = option.name;
        switch (option.pathKind) {
            case "file":
                return `${value} === undefined ? undefined : toRootedFilePath(${value}, currentDirectory)`;
            case "directory":
                return option.type === "[]string"
                    ? `${value}?.map(value => toRootedDirectoryPath(value, currentDirectory))`
                    : `${value} === undefined ? undefined : toRootedDirectoryPath(${value}, currentDirectory)`;
            case "fileOrDirectory":
                return `${value} === undefined ? undefined : toRootedPath(${value}, currentDirectory)`;
            default:
                throw new Error(`Unsupported API path kind for ${option.name}: ${option.pathKind}`);
        }
    };
    return `${header}
import type { RootedDirectoryPath } from "../ast/index.ts";
import type { CompilerOptions } from "./compilerOptions.generated.ts";
import {
    toRootedDirectoryPath,
    toRootedFilePath,
    toRootedPath,
} from "./path.ts";
import type { RawCompilerOptions } from "./proto.generated.ts";

export function prepareCompilerOptions(options: RawCompilerOptions, currentDirectory: RootedDirectoryPath): CompilerOptions {
    const {
        ${pathOptions.map(option => `${option.name},`).join("\n        ")}
        ...rest
    } = options;
    const result = {
        ...rest,
        ${pathOptions.map(option => `${option.name}: ${converter(option)},`).join("\n        ")}
    };
    return result;
}
`;
}

function optionsEquality(name: string, fields: { name: string; type: GoCompilerOptionType; }[]): string {
    return `func (options *${name}) Equals(other *${name}) bool {
    if options == other { return true }
    if options == nil || other == nil { return false }
    ${
        fields.map(field => {
            const a = `options.${field.name}`;
            const b = `other.${field.name}`;
            let differs: string;
            switch (field.type) {
                case "*int":
                    differs = `${a} != ${b} && (${a} == nil || ${b} == nil || *${a} != *${b})`;
                    break;
                case "[]string":
                case "[]PluginImport":
                case "[]tspath.RootedDirectoryPath":
                    differs = `(${a} == nil) != (${b} == nil) || !slices.Equal(${a}, ${b})`;
                    break;
                case "*collections.OrderedMap[string, []string]":
                    differs = `!${a}.EqualFunc(${b}, func(a, b []string) bool {
    return (a == nil) == (b == nil) && slices.Equal(a, b)
})`;
                    break;
                default:
                    differs = `${a} != ${b}`;
            }
            return `if ${differs} { return false }`;
        }).join("\n")
    }
    return true
}
`;
}

function storedOptions(name: string, declarations: StoredDeclaration[]): string {
    return `type ${name} struct {
${name === "BuildOptions" ? "_ noCopy\n" : ""}
${declarations.map(option => `${sectionComment(option.field.section)}${option.field.name} ${option.field.type} \`json:"${option.name},omitzero"\``).join("\n")}
}
`;
}

function zeroValue(option: CompilerOption): string {
    const kind = optionKind(option);
    return kind === "Boolean" ? "core.TSUnknown" : kind === "String" ? '""' : kind === "Enum" ? "0" : "nil";
}

function showConfig(): string {
    const serializedOptions = options.compilerOptions.filter(option => {
        const declaration = option.declaration;
        return option.showConfig !== false && declaration && declaration.category?.go !== "diagnostics.Command_line_Options" && declaration.category?.go !== "diagnostics.Output_Formatting";
    });
    const enumOptions = serializedOptions.filter(option => optionKind(option) === "Enum");
    assert.equal(new Set(enumOptions.map(option => option.type)).size, enumOptions.length, "ShowConfig enum types must have a single option map");
    return `func serializeCompilerOptions(options *core.CompilerOptions, configFilePath tspath.RootedFilePath, caseSensitivity tspath.CaseSensitivity) *collections.OrderedMap[string, any] {
    result := collections.NewOrderedMapWithSizeHint[string, any](32)
${
        serializedOptions.map(option => {
            const field = `options.${fieldName(option)}`;
            const name = JSON.stringify(option.name);
            const declaration = option.declaration!;
            let value = field;
            let condition = `${field} != ${zeroValue(option)}`;
            switch (optionKind(option)) {
                case "Enum":
                    return `if ${condition} {
    if value := serializeCompilerOptionEnum(${field}); value != "" {
        result.Set(${name}, value)
    }
}`;
                case "Boolean":
                    condition = `${field} == core.TSTrue || ${field} == core.TSFalse`;
                    value = `${field} == core.TSTrue`;
                    break;
                case "String":
                    if (option.pathKind === "file" || option.pathKind === "directory") {
                        value = `serializeCompilerOptionPath(${field}.AsPath(), configFilePath, caseSensitivity)`;
                    }
                    else if (option.pathKind === "fileOrDirectory") {
                        value = `serializeCompilerOptionPath(${field}, configFilePath, caseSensitivity)`;
                    }
                    break;
                case "List": {
                    const element = options.elements[option.name];
                    if (option.pathKind === "directory") {
                        assert.equal(option.type, "[]string", `Unsupported file path list: ${option.name}`);
                        value = `core.Map(${field}, func(value tspath.RootedDirectoryPath) string {
    if value == "" { return "" }
    return serializeCompilerOptionPath(value.AsPath(), configFilePath, caseSensitivity)
})`;
                    }
                    else if (element?.kind === "Enum") {
                        assert.equal(option.type, "[]string", `Unsupported enum list: ${option.name}`);
                        value = `serializeCompilerOptionEnumList(${field}, ${options.enumMaps[option.name].goName})`;
                    }
                    break;
                }
            }
            return `if ${condition} {
    result.Set(${name}, ${value})
}`;
        }).join("\n")
    }
    return result
}

func serializeCompilerOptionEnum(value any) string {
    switch value := value.(type) {
${
        enumOptions.map(option => {
            const seen = new Set<string>();
            const entries = options.enumMaps[option.name].values.filter(entry => {
                const value = goValue(entry.value);
                if (seen.has(value)) return false;
                seen.add(value);
                return true;
            });
            return `case core.${option.type}:
${entries.map(entry => `if value == ${goValue(entry.value)} { return ${JSON.stringify(entry.name)} }`).join("\n")}`;
        }).join("\n")
    }
    }
    return ""
}
`;
}

function configDirSubstitution(): string {
    const substitutedOptions = options.compilerOptions.filter(option => !option.pathKind && option.declaration?.allowConfigDirTemplateSubstitution);
    return `func handleOptionConfigDirTemplateSubstitution(compilerOptions *parsedCompilerOptions, basePath tspath.RootedDirectoryPath) {
    if compilerOptions == nil { return }
${
        substitutedOptions.map(option => {
            const field = `compilerOptions.${fieldName(option)}`;
            switch (option.type) {
                case "string":
                    return `if startsWithConfigDirTemplate(${field}) {
    ${field} = getSubstitutedPathWithConfigDirTemplate(${field}, basePath)
}`;
                case "[]string":
                    return `if substitution := getSubstitutedStringArrayWithConfigDirTemplate(${field}, basePath); substitution != nil {
    ${field} = substitution
}`;
                case "*collections.OrderedMap[string, []string]":
                    return `{
    var paths *collections.OrderedMap[string, []string]
    for k, v := range ${field}.Entries() {
        if substitution := getSubstitutedStringArrayWithConfigDirTemplate(v, basePath); substitution != nil {
            if paths == nil {
                paths = ${field}.Clone()
                ${field} = paths
            }
            paths.Set(k, substitution)
        }
    }
}`;
                default:
                    throw new Error(`Unsupported configDir substitution type for ${option.name}: ${option.type}`);
            }
        }).join("\n")
    }
    for key, value := range compilerOptions.unresolvedPaths {
        option := CommandLineCompilerOptionsMap.Get(key)
        if option.Kind == CommandLineOptionTypeList {
            value = core.Map(ParseStringArray(value), func(path string) any {
                return getSubstitutedPathWithConfigDirTemplate(path, basePath)
            })
        } else {
            value = getSubstitutedPathWithConfigDirTemplate(ParseString(value), basePath)
        }
        ParseCompilerOptions(key, value, compilerOptions.CompilerOptions)
    }
    clear(compilerOptions.unresolvedPaths)
}
`;
}

function mergeCompilerOptions(): string {
    return `func mergeCompilerOptionFields(targetOptions, sourceOptions *core.CompilerOptions, explicitNullFields collections.Set[string]) {
${
        options.compilerOptions.map(option => {
            const field = fieldName(option);
            const zero = zeroValue(option);
            return `if explicitNullFields.Has(${JSON.stringify(option.name)}) {
    targetOptions.${field} = ${zero}
} else if sourceOptions.${field} != ${zero} {
    targetOptions.${field} = sourceOptions.${field}
}`;
        }).join("\n")
    }
}
`;
}

function transpileOptions(): string {
    const transformedOptions = options.compilerOptions.filter(option => option.transpile);
    return `${header}
package transpile

import "github.com/microsoft/TypeScript/tsc/internal/core"

func setOptionsForTranspile(options *core.CompilerOptions, declaration bool) {
${
        transformedOptions.map(option => {
            const { value, declarationValue, unless } = option.transpile!;
            const field = `options.${fieldName(option)}`;
            const assigned = value === "clear" ? zeroValue(option) : value ? "core.TSTrue" : "core.TSFalse";
            let code = `${field} = ${assigned}`;
            if (declarationValue === "preserve") code = `if !declaration { ${code} }`;
            else if (declarationValue !== undefined) code = `if declaration { ${field} = ${declarationValue ? "core.TSTrue" : "core.TSFalse"} } else { ${code} }`;
            if (unless) code = `if !options.${fieldName(options.compilerOptions.find(option => option.name === unless)!)}.IsTrue() { ${code} }`;
            return code;
        }).join("\n")
    }
}
`;
}

function generateBuildInfoOptions(): string {
    const storedOptions = options.compilerOptions.filter(option => option.declaration?.affectsBuildInfo);
    return `// ForEachCompilerOptionAffectingBuildInfo visits nonzero options in CompilerOptions field order.
func ForEachCompilerOptionAffectingBuildInfo(options *core.CompilerOptions, fn func(option *CommandLineOption, value any)) {
${
        storedOptions.map(option =>
            `if options.${fieldName(option)} != ${zeroValue(option)} {
    fn(CommandLineCompilerOptionsMap.Get(${JSON.stringify(option.name)}), options.${fieldName(option)})
}`
        ).join("\n")
    }
}
`;
}

export function generateOptionComparisons(model = options): string {
    const comparisons = [
        ["SemanticDiagnostics", "affectsSemanticDiagnostics"],
        ["DeclarationPath", "affectsDeclarationPath"],
        ["Emit", "affectsEmit"],
    ] as const;
    return `${
        comparisons.map(([name, flag]) => {
            const expressions = model.compilerOptions.flatMap(option => {
                const declaration = option.declaration;
                if (!declaration?.[flag]) return [];
                const kind = optionKind(option);
                assert(kind === "Boolean" || kind === "String" || kind === "Enum", `Unsupported comparison type for ${option.name}: ${option.type}`);
                const value = (receiver: string) => {
                    const field = `${receiver}.${fieldName(option)}`;
                    if (declaration.strictFlag) return `${receiver}.GetStrictOptionValue(${field})`;
                    return field;
                };
                return [`${value("oldOptions")} != ${value("newOptions")}`];
            });
            return `func CompilerOptionsAffect${name}(oldOptions *core.CompilerOptions, newOptions *core.CompilerOptions) bool {
    if oldOptions == newOptions { return false }
    if oldOptions == nil || newOptions == nil { return true }
    return ${expressions.join(" ||\n") || "false"}
}
`;
        }).join("\n")
    }
`;
}

function enumStrings(): string {
    return options.enums.filter(enumDef => enumDef.stringer).map(enumDef => {
        const stringer = enumDef.stringer!;
        return `func (value ${enumDef.name}) String() string {
    switch value {
    case 0:
        panic("should not use zero value of ${enumDef.name}")
    ${
            enumDef.members.filter(member => typeof member.value === "number" && member.value !== 0).map(member => {
                const constant = `${enumDef.name}${member.name}`;
                const text = stringer === "name" ? member.name : options.enumMaps[stringer.enumMap].values.find(entry => typeof entry.value === "object" && entry.value.go === `core.${constant}`)?.name;
                assert(text, `Missing display name for ${constant}`);
                return `case ${constant}: return ${JSON.stringify(text)}`;
            }).join("\n")
        }
    default:
        panic("unhandled case in ${enumDef.name}.String")
    }
}
`;
    }).join("\n");
}

function numericEnums(): string {
    return `${
        options.enums.map(enumDef =>
            `type ${enumDef.name} int32

const (
${enumDef.members.map(member => `${member.comment ? "// " + member.comment.replaceAll("\n", "\n// ") + "\n" : ""}${enumDef.name}${member.name} ${enumDef.name} = ${typeof member.value === "number" ? member.value : enumDef.name + member.value}${member.trailingComment ? " // " + member.trailingComment : ""}`).join("\n")}
)
`
        ).join("\n")
    }

var ModuleKindToModuleResolutionKind = map[ModuleKind]ModuleResolutionKind{
${options.enums.find(enumDef => enumDef.name === "ModuleKind")!.members.filter(member => member.moduleResolution).map(member => `ModuleKind${member.name}: ModuleResolutionKind${member.moduleResolution},`).join("\n")}
}
`;
}

const declarationFields = new Map([
    ["shortName", "ShortName"],
    ["isFilePath", "IsFilePath"],
    ["pathKind", "PathKind"],
    ["isTSConfigOnly", "IsTSConfigOnly"],
    ["isCommandLineOnly", "IsCommandLineOnly"],
    ["description", "Description"],
    ["defaultValueDescription", "DefaultValueDescription"],
    ["showInSimplifiedHelpView", "ShowInSimplifiedHelpView"],
    ["category", "Category"],
    ["extraValidation", "extraValidation"],
    ["minValue", "minValue"],
    ["listPreserveFalsyValues", "listPreserveFalsyValues"],
]);

function declarationLiteral(declaration: Declaration): string {
    const { name, kind } = declaration;
    const properties = [`Name: ${JSON.stringify(name)},`, `Kind: CommandLineOptionType${kind},`];
    for (const [key, value] of Object.entries(declaration)) {
        const goName = declarationFields.get(key);
        if (goName === undefined || value === undefined) continue;
        const goValueText = key === "extraValidation"
            ? "extraValidationLocale"
            : key === "pathKind"
            ? `CommandLineOptionPathKind${value[0].toUpperCase() + value.slice(1)}`
            : goValue(value);
        properties.push(`${goName}: ${goValueText},`);
    }
    return `{\n${properties.join("\n")}\n}`;
}

function declarations(): string {
    const all = compilerDeclarations();
    const groups = ["commonOptionsWithBuild", "optionsForCompiler"] as const;
    const arrays: [string, Declaration[]][] = [
        ...groups.map(group => [group, orderByName(all.filter(declaration => declaration.group === group), options.declarationOrder[group], group)] as [string, Declaration[]]),
        ["typeAcquisitionDecls", options.typeAcquisition],
    ];
    return `var OptionsDeclarations = slices.Concat(commonOptionsWithBuild, optionsForCompiler)

var BuildOpts = slices.Concat(commonOptionsWithBuild, OptionsForBuild)

${arrays.map(([name, values]) => `var ${name} = []*CommandLineOption{\n${values.map(declaration => declarationLiteral(declaration) + ",").join("\n")}\n}`).join("\n\n")}

var commandLineOptionElements = map[string]*CommandLineOption{
${Object.entries(options.elements).map(([name, declaration]) => `${JSON.stringify(name)}: ${declarationLiteral(declaration)},`).join("\n")}
}

var TscBuildOption = CommandLineOption${declarationLiteral(options.buildOptions[0])}

var OptionsForBuild = []*CommandLineOption{
    &TscBuildOption,
    ${options.buildOptions.slice(1).map(option => declarationLiteral(option) + ",").join("\n")}
}
`;
}

function rootDeclarations(): string {
    const elementOptions = {
        compilerOptions: "CommandLineCompilerOptionsMap",
        typeAcquisition: "commandLineOptionsToMap(typeAcquisitionDecls)",
        extends: `commandLineOptionsToMap([]*CommandLineOption{${declarationLiteral(options.elements.extends)}})`,
    };
    return `${
        options.rootOptions.filter(option => option.variable).map(option => {
            let literal = declarationLiteral(option);
            if (option.elementOptions) literal = literal.slice(0, -1) + `ElementOptions: ${elementOptions[option.elementOptions]},\n}`;
            return `var ${option.variable} = &CommandLineOption${literal}`;
        }).join("\n\n")
    }

var tsconfigRootOptionsMap = &CommandLineOption{
    Name: "undefined",
    Kind: CommandLineOptionTypeObject,
    ElementOptions: commandLineOptionsToMap([]*CommandLineOption{
        ${options.rootOptions.map(option => (option.variable ?? declarationLiteral(option)) + ",").join("\n")}
    }),
}
`;
}

function enumMaps(): string {
    return `${Object.values(options.enumMaps).map(map => `var ${map.goName} = collections.NewOrderedMapFromList([]collections.MapEntry[string, any]{\n${map.values.map(entry => `{Key: ${JSON.stringify(entry.name)}, Value: ${goValue(entry.value)}},`).join("\n")}\n})`).join("\n\n")}

var commandLineOptionEnumMap = map[string]*collections.OrderedMap[string, any]{
${Object.entries(options.enumMaps).map(([name, map]) => `${JSON.stringify(name)}: ${map.goName},`).join("\n")}
}

var commandLineOptionDeprecated = map[string]*collections.Set[string]{
${Object.entries(options.enumMaps).filter(([, map]) => map.deprecatedKeys).map(([name, map]) => `${JSON.stringify(name)}: collections.NewSetFromItems(${map.deprecatedKeys!.map(key => JSON.stringify(key)).join(", ")}),`).join("\n")}
}

var targetToLibMap = map[core.ScriptTarget]string{
${options.enums.find(enumDef => enumDef.name === "ScriptTarget")!.members.filter(member => member.lib).toReversed().map(member => `core.ScriptTarget${member.name}: ${JSON.stringify(member.lib)},${member.libComment ? " // " + member.libComment : ""}`).join("\n")}
}
`;
}

function parserAssignment(option: CompilerOption): string {
    const target = `allOptions.${fieldName(option)}`;
    switch (option.pathKind) {
        case "file":
            return `${target} = parseFileName(value)`;
        case "directory":
            return option.type === "[]string"
                ? `${target} = parseDirectoryNames(value)`
                : `${target} = parseDirectoryName(value)`;
        case "fileOrDirectory":
            return `${target} = parseFileOrDirectoryName(value)`;
        case "sourceMapLocation":
            return `${target} = tspath.ToSourceMapLocation(ParseString(value))`;
    }
    if (option.name === "lib") {
        return `if libs, ok := value.([]string); ok { ${target} = libs } else { ${target} = ParseStringArray(value) }`;
    }
    if (option.name === "plugins") {
        return `if plugins, ok := value.([]any); ok {
            ${target} = core.Map(plugins, func(plugin any) core.PluginImport {
                if pluginMap, isMap := plugin.(*collections.OrderedMap[string, any]); isMap {
                    return core.PluginImport{Name: ParseString(pluginMap.GetOrZero("name"))}
                }
                return core.PluginImport{}
            })
        }`;
    }
    const functions: Partial<Record<CompilerOption["type"], string>> = {
        "Tristate": "ParseTristate",
        "string": "ParseString",
        "*int": "parseNumber",
        "[]string": "ParseStringArray",
        "*collections.OrderedMap[string, []string]": "parseStringMap",
    };
    const parser = functions[option.type];
    assert(option.type !== "[]PluginImport", "Plugin options require the plugin parser");
    return `${target} = ${parser ?? `floatOrInt32ToFlag[core.${option.type}]`}(value)`;
}

function parser(): string {
    return `func parseCompilerOptions(key string, value any, allOptions *core.CompilerOptions) (foundKey bool) {
    if option := CommandLineCompilerOptionsMap.Get(key); option != nil { key = option.Name }
    switch key {
    ${options.compilerOptions.map(option => `case ${[option.name, ...(option.parseAliases ?? [])].map(name => JSON.stringify(name)).join(", ")}:\n${parserAssignment(option)}`).join("\n")}
    default:
        return false
    }
    return true
}

func getDefaultCompilerOptions(configFileName tspath.RootedFilePath) *parsedCompilerOptions {
   options := &core.CompilerOptions{}
   if configFileName != "" && configFileName.BaseName() == "jsconfig.json" {
       options = &core.CompilerOptions{
        ${
        options.compilerOptions.filter(option => option.jsconfigDefault !== undefined).map(option => {
            const value = option.jsconfigDefault!;
            const expression = typeof value === "boolean" ? `core.TS${value ? "True" : "False"}` : typeof value === "number" ? `new(${value})` : JSON.stringify(value);
            return `${fieldName(option)}: ${expression},`;
        }).join("\n")
    }
        }
    }
    return &parsedCompilerOptions{
        CompilerOptions: options,
        unresolvedPaths: make(unresolvedCompilerOptionPaths),
    }
}

func getDefaultTypeAcquisition(configFileName tspath.RootedFilePath) *core.TypeAcquisition {
    if configFileName != "" && configFileName.BaseName() == "jsconfig.json" {
        return &core.TypeAcquisition{
            ${options.typeAcquisition.filter(option => option.jsconfigDefault !== undefined).map(option => `${option.field.name}: core.TS${option.jsconfigDefault ? "True" : "False"},`).join("\n")}
        }
    }
    return &core.TypeAcquisition{}
}
`;
}

function storedParser(name: string, declarations: StoredDeclaration[]): string {
    return `func Parse${name}(key string, value any, allOptions *core.${name}) {
    if value == nil { return }
    if allOptions == nil { return }
    ${name === "BuildOptions" ? "if option := BuildNameMap.Get(key); option != nil { key = option.Name }" : ""}
    switch key {
    ${
        declarations.map(option => {
            const stored: CompilerOption = { name: option.name, goName: option.field.name, type: option.field.type };
            return `case ${JSON.stringify(option.name)}:\n${parserAssignment(stored)}`;
        }).join("\n")
    }
    }
}
`;
}

export function generateOptions(): Map<string, string> {
    validateOptions(options);
    const buildOptions = options.buildOptions.filter((option): option is StoredDeclaration => option.field !== undefined);
    return new Map([
        ["packages/typescript/src/api/compilerOptions.generated.ts", generateCompilerOptionsAPI()],
        ["packages/typescript/src/api/prepareCompilerOptions.generated.ts", generatePrepareCompilerOptionsAPI()],
        [
            "tsc/internal/core/options_generated.go",
            `${header}
package core

import (
    "slices"

    "github.com/microsoft/TypeScript/tsc/internal/collections"
    "github.com/microsoft/TypeScript/tsc/internal/tspath"
)

//go:generate npx hereby generate:compileroptions

${coreOptions()}
${numericEnums()}
${enumStrings()}
${storedOptions("TypeAcquisition", options.typeAcquisition)}
${storedOptions("BuildOptions", orderByName(buildOptions, options.buildOptionFieldOrder, "BuildOptions fields"))}
`,
        ],
        ["tsc/internal/transpile/options_generated.go", transpileOptions()],
        [
            "tsc/internal/tsoptions/declarations_generated.go",
            `${header}
package tsoptions

import (
    "slices"

    "github.com/microsoft/TypeScript/tsc/internal/collections"
    "github.com/microsoft/TypeScript/tsc/internal/core"
    "github.com/microsoft/TypeScript/tsc/internal/diagnostics"
)

${declarations()}
${rootDeclarations()}
${enumMaps()}
`,
        ],
        [
            "tsc/internal/tsoptions/options_generated.go",
            `${header}
package tsoptions

import (
    "github.com/microsoft/TypeScript/tsc/internal/collections"
    "github.com/microsoft/TypeScript/tsc/internal/core"
    "github.com/microsoft/TypeScript/tsc/internal/tspath"
)

${parser()}
${storedParser("TypeAcquisition", options.typeAcquisition)}
${storedParser("BuildOptions", buildOptions)}
${generateOptionComparisons()}
${generateBuildInfoOptions()}
${mergeCompilerOptions()}
${configDirSubstitution()}
${showConfig()}
`,
        ],
        [
            "tsc/internal/testrunner/options_generated.go",
            `${header}
package testrunner

import "github.com/microsoft/TypeScript/tsc/internal/collections"

var compilerVaryBy = collections.NewSetFromItems(
${
                options.compilerOptions.filter(option =>
                    option.declaration && !option.declaration.isCommandLineOnly &&
                    (optionKind(option) === "Boolean" || optionKind(option) === "Enum")
                ).map(option => option.name.toLowerCase()).sort().map(name => `${JSON.stringify(name)},`).join("\n")
            }
)
`,
        ],
        ...(["tsconfig", "jsconfig"] as const).map(name => [`packages/typescript/schemas/${name}.schema.json`, JSON.stringify(generateConfigSchema(name), null, 4) + "\n"] as [string, string]),
    ]);
}

export default async function generate(force = false): Promise<void> {
    const inputs = [...sourceFiles.map(file => path.join(import.meta.dirname, file)), diagnosticsFile];
    const outputs = generateOptions();
    const changed: GeneratedFile[] = [];
    for (const [fileName, content] of outputs) {
        const file = new GeneratedFile(path.join(repoRoot, fileName), inputs);
        if (file.isCurrent(force)) continue;
        file.write(content);
        changed.push(file);
    }
    if (changed.length) {
        await formatFiles(changed.map(file => file.fileName));
        for (const file of changed) file.markCurrent();
    }
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
    await generate(parseGeneratorArgs({}).force);
}

